                style={{ display: 'flex', gap: '0.875rem', alignItems: 'center', flexWrap: 'wrap' }}
              >
                <a
                  href="#cta"
                  data-cta-primary
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '0.6rem',
                    background: INK,
                    color: PAPER,
                    padding: '0.9rem 1.75rem',
                    fontFamily: 'var(--font-body)',
