import * as THREE from 'three';
import vertexShader from '../shaders/img.vert?raw';
import fragmentShader from '../shaders/img.frag?raw';

// DOM elements
const domWrapper = document.getElementById('wrapper');
let canvas;

// Three.js core objects
let scene;
let camera;
let renderer;
let geometry;

// State variables
let time = 0;
let padding = 0;
let isNoFix = false;
let isFixedWithPadding = false;
let viewportWidth;
let viewportHeight;
let prevScrollY = 0;
let strength = 0;

// Environment variables
const dpr = window.devicePixelRatio;
let colorBackground;

// Uniform variables for shaders
const resolution = new THREE.Vector2(1, 1);
const scrollOffset = new THREE.Vector2(0, 0);
const sharedUniforms = {
	u_resolution: { value: resolution },
	u_scrollOffset: { value: scrollOffset },
	u_time: { value: 0 },
	u_strength: { value: 0 },
};

// Items tracking
const itemList = [];

/**
 * Initialize the application
 */
function init() {
	colorBackground = getComputedStyle(document.documentElement).getPropertyValue('--color-background');

	// Set up Three.js scene
	setupThreeJS();

	// Create meshes for all images
	createImageMeshes();

	// Set up event listeners
	setupEventListeners();

	// Initialize state
	time = performance.now() / 1000;
	prevScrollY = window.scrollY;

	// Start animation loop
	animate();

	console.log(
		// credit
		'%c Created by Lusion: https://lusion.co/',
		'border:2px solid gray; padding:5px; font-family:monospace; font-size:11px;',
	);
}

/**
 * Set up Three.js scene, camera and renderer
 */
function setupThreeJS() {
	canvas = document.querySelector('#canvas');
	scene = new THREE.Scene();
	camera = new THREE.Camera();
	renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
	renderer.setSize(window.innerWidth, window.innerHeight);
	renderer.setClearColor(colorBackground);
	geometry = new THREE.PlaneGeometry(1, 1, 1, 1);
}

/**
 * Create meshes for all image containers
 */
function createImageMeshes() {
	const domImageContainerList = document.querySelectorAll('.image');
	const textureLoader = new THREE.TextureLoader();

	for (let i = 0; i < domImageContainerList.length; i++) {
		const domContainer = domImageContainerList[i];
		const mesh = new THREE.Mesh(
			geometry,
			new THREE.ShaderMaterial({
				uniforms: {
					u_texture: { value: textureLoader.load(`/images/${i}.webp`) },
					u_domXY: { value: new THREE.Vector2(0, 0) },
					u_domWH: { value: new THREE.Vector2(1, 1) },
					u_resolution: sharedUniforms.u_resolution,
					u_scrollOffset: sharedUniforms.u_scrollOffset,
					u_time: sharedUniforms.u_time,
					u_strength: sharedUniforms.u_strength,
					u_rands: { value: new THREE.Vector4(0, 0, 0, 0) },
					u_id: { value: i },
				},
				vertexShader,
				fragmentShader,
				side: THREE.DoubleSide,
			}),
		);

		itemList.push({
			domContainer,
			mesh,
			width: 1,
			height: 1,
			x: 0,
			top: 0,
		});

		scene.add(mesh);
		mesh.frustumCulled = false;
	}
}

/**
 * Set up all event listeners
 */
function setupEventListeners() {
	// Resize events
	window.addEventListener('resize', onResize);
	if (window.ResizeObserver) {
		new ResizeObserver(onResize).observe(domWrapper);
	}

	// Overlay toggle
	setupOverlayEvents();

	// Settings panel
	setupSettingsEvents();
}

/**
 * Set up overlay toggle events
 */
function setupOverlayEvents() {
	let aboutToggle = false;

	document.getElementById('overlay-open').addEventListener('click', () => {
		aboutToggle = !aboutToggle;
		document.documentElement.classList.toggle('is-overlay-active', aboutToggle);
	});

	document.getElementById('overlay-close').addEventListener('click', () => {
		aboutToggle = false;
		document.documentElement.classList.toggle('is-overlay-active', aboutToggle);
	});
}

/**
 * Set up settings panel events
 */
function setupSettingsEvents() {
	document.querySelector('#settings__button').addEventListener('click', () => {
		document.querySelector('#settings').classList.toggle('is-active');
	});

	document.querySelectorAll('#settings__items li').forEach((li) => {
		li.addEventListener('click', () => {
			document.querySelectorAll('#settings__items li').forEach((item) => {
				item.classList.remove('is-active');
			});

			li.classList.add('is-active');

			isNoFix = li.dataset.noFix === '1';
			isFixedWithPadding = li.dataset.fixedWithPadding === '1';
			document.documentElement.classList.toggle('no-fix', isNoFix);
			onResize();

			document.querySelector('#settings').classList.toggle('is-active', false);
		});
	});
	document.querySelectorAll('#settings__items li')[0].click();
}

/**
 * Handle resize events
 */
function onResize() {
	padding = isFixedWithPadding && !isNoFix ? 0.25 : 0;

	viewportWidth = domWrapper.clientWidth;
	viewportHeight = window.innerHeight;

	const canvasHeight = viewportHeight * (1 + padding * 2);

	resolution.set(viewportWidth, canvasHeight);

	renderer.setSize(viewportWidth * dpr, canvasHeight * dpr);
	canvas.style.width = `${viewportWidth}px`;
	canvas.style.height = `${canvasHeight}px`;

	scrollOffset.set(window.scrollX, window.scrollY);

	updateItemPositions();
}

/**
 * Update item positions and dimensions
 */
function updateItemPositions() {
	for (let i = 0; i < itemList.length; i++) {
		const item = itemList[i];
		const rect = item.domContainer.getBoundingClientRect();

		item.width = rect.width;
		item.height = rect.height;
		item.x = rect.left + scrollOffset.x;
		item.y = rect.top + scrollOffset.y;

		item.mesh.material.uniforms.u_domWH.value.set(item.width, item.height);
	}
}

/**
 * Animation loop
 */
function animate() {
	requestAnimationFrame(animate);

	const scrollY = window.scrollY;
	const scrollDelta = scrollY - prevScrollY;

	// Calculate time delta
	const newTime = performance.now() / 1000;
	const dt = newTime - time;
	time = newTime;

	// Update animation strength based on scroll speed
	updateStrength(scrollDelta, dt);

	// Update uniform values
	updateUniforms(dt, scrollY);

	// Position canvas based on scroll
	updateCanvasPosition();

	// Update and optimize mesh visibility
	updateMeshes(dt);

	// Render the scene
	renderer.render(scene, camera);

	prevScrollY = scrollY;
}

/**
 * Update animation strength based on scroll speed
 */
function updateStrength(scrollDelta, dt) {
	const targetStrength = (Math.abs(scrollDelta) * 10) / viewportHeight;

	strength *= Math.exp(-dt * 10);
	strength += Math.min(targetStrength, 5);
}

/**
 * Update uniform values for shaders
 */
function updateUniforms(dt, scrollY) {
	sharedUniforms.u_time.value += dt;
	sharedUniforms.u_strength.value = Math.min(1, strength);
	scrollOffset.set(window.scrollX, scrollY - viewportHeight * padding);
}

/**
 * Update canvas position based on settings
 */
function updateCanvasPosition() {
	if (!isNoFix) {
		canvas.style.transform = `translate(${scrollOffset.x}px, ${scrollOffset.y}px)`;
	} else {
		canvas.style.transform = `translateZ(0)`;
	}
}

/**
 * Update meshes and optimize visibility
 */
function updateMeshes(dt) {
	const canvasTop = scrollOffset.y;
	const canvasBottom = canvasTop + resolution.y;

	for (let i = 0; i < itemList.length; i++) {
		const item = itemList[i];

		// Update position
		item.mesh.material.uniforms.u_domXY.value.set(item.x, item.y);

		// Randomly update random values
		if (Math.random() > Math.exp(-dt * 25 * (1 + strength))) {
			item.mesh.material.uniforms.u_rands.value = new THREE.Vector4(Math.random(), Math.random(), Math.random(), Math.random());
		}

		// Optimize by hiding items that are not visible
		item.mesh.visible = item.y < canvasBottom && item.y + item.height > canvasTop;
	}
}

// wait one frame before initializing to ensure the css properties are set
requestAnimationFrame(init);

import React, { useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useLenis } from 'lenis/react';

gsap.registerPlugin(ScrollTrigger);

// Assembly sequence: chaos → explosion → head emerging → assembled
const FRAMES: { src: string; blend: React.CSSProperties['mixBlendMode'] }[] = [
  { src: '/assets/4.png',         blend: 'multiply' }, // fully scattered
  { src: '/assets/3.png',         blend: 'multiply' }, // slight grouping
  { src: '/assets/2.png',         blend: 'multiply' }, // energy burst
  { src: '/assets/5.png',         blend: 'multiply' }, // head emerging
  { src: '/assets/puzzle-pb.png', blend: 'normal'   }, // assembled (dark bg)
];

// ── Palette ──────────────────────────────────────────────────────────────
const PAPER  = '#F3EDE3';
const DARK   = '#0D0A07';
const INK    = '#0D0A07';
const LIGHT  = '#F3EDE3';
const RED    = '#B91C1C';

const INK50  = 'rgba(13,10,7,0.50)';
const INK28  = 'rgba(13,10,7,0.28)';
const INK14  = 'rgba(13,10,7,0.14)';
const INK08  = 'rgba(13,10,7,0.08)';

const PRODUCTS = [
  { name: 'Aurora CRM',     live: true  },
  { name: 'Elysian Lex',    live: false },
  { name: 'Living Doc',     live: false },
];

export default function AuroraHero() {
  const sectionRef  = useRef<HTMLElement>(null);
  const stickyRef   = useRef<HTMLDivElement>(null);
  const headlineRef = useRef<HTMLHeadingElement>(null);
  const subtextRef  = useRef<HTMLParagraphElement>(null);
  const frameRefs   = useRef<(HTMLImageElement | null)[]>([]);
  const progressRef = useRef<HTMLDivElement>(null);

  const lenis = useLenis();

  // Sync Lenis smooth scroll with GSAP ScrollTrigger
  useEffect(() => {
    if (!lenis) return;
    lenis.on('scroll', ScrollTrigger.update);
    return () => { lenis.off('scroll', ScrollTrigger.update); };
  }, [lenis]);

  useEffect(() => {
    const section  = sectionRef.current;
    const sticky   = stickyRef.current;
    const headline = headlineRef.current;
    const subtext  = subtextRef.current;
    if (!section || !sticky) return;

    const frames = frameRefs.current.filter(Boolean) as HTMLImageElement[];
    if (frames.length !== FRAMES.length) return;

    // ── Initial states ────────────────────────────────────────────────────
    gsap.set(frames, { opacity: 0 });
    gsap.set(frames[0], { scale: 1.06, opacity: 0 });

    // ── Entry animation (load, not scroll) ───────────────────────────────
    const reveals = sticky.querySelectorAll<HTMLElement>('[data-hero-reveal]');
    gsap.set(reveals, { y: 52, opacity: 0 });

    // Frame 0 — chaos image enters first, behind the text
    gsap.to(frames[0], {
      scale: 1, opacity: 1,
      duration: 1.8, ease: 'power3.out', delay: 0.15,
    });

    // Text content staggers in after
    gsap.to(reveals, {
      y: 0, opacity: 1,
      duration: 1.1, ease: 'power4.out',
      stagger: 0.09, delay: 0.45,
    });

    // ── Signal header about hero phase (light vs dark) ───────────────────
    const emitPhase = (isDark: boolean) => {
      window.dispatchEvent(new CustomEvent('aurora:hero-phase-dark', { detail: isDark }));
    };
    emitPhase(false); // initial: light

    // ── Scroll-driven timeline ────────────────────────────────────────────
    // Section is 500vh tall; inner div is CSS sticky — GSAP maps scroll to timeline.
    // Timeline positions (unit = seconds, scrub normalises them to scroll distance):
    //
    //   0.0 → 0.4   frame 0 only (chaos visible, page is ivory)
    //   0.4 → 0.9   frame 0→1 cross-fade
    //   0.9 → 1.1   frame 1 only
    //   1.1 → 1.6   frame 1→2 cross-fade
    //   1.2 → 2.0   bg: ivory → dark  (overlaps frame 2 appearing)
    //   1.6 → 2.1   frame 2 only (energy burst — bg going dark)
    //   2.1 → 2.6   frame 2→3 cross-fade (bg now fully dark)
    //   2.6 → 2.9   frame 3 only
    //   2.9 → 3.4   frame 3→4 cross-fade (puzzle-pb assembles in dark)
    //   3.4+        assembled state holds

    const tl = gsap.timeline({
      scrollTrigger: {
        trigger: section,
        start: 'top top',
        end: 'bottom bottom',
        scrub: 1.6,
        onUpdate: (self) => {
          // Signal header when hero bg turns dark (bg transition starts at ~35% progress)
          emitPhase(self.progress > 0.35);
        },
        onLeaveBack: () => emitPhase(false),
        onLeave: () => emitPhase(true),
      },
      defaults: { ease: 'none' },
    });

    // Frame 0 → 1
    tl.to(frames[0], { opacity: 0, duration: 0.5 }, 0.4)
      .to(frames[1], { opacity: 1, duration: 0.5 }, 0.4);

    // Frame 1 → 2
    tl.to(frames[1], { opacity: 0, duration: 0.5 }, 1.1)
      .to(frames[2], { opacity: 1, duration: 0.5 }, 1.1);

    // Background: ivory → dark (starts as frame 2 becomes visible)
    tl.to(sticky, { backgroundColor: DARK, duration: 0.8 }, 1.2);

    // Text colours transition as bg goes dark
    if (headline) tl.to(headline, { color: LIGHT, duration: 0.7 }, 1.3);
    if (subtext)  tl.to(subtext,  { color: 'rgba(243,237,227,0.65)', duration: 0.7 }, 1.3);

    const mutedEls = sticky.querySelectorAll<HTMLElement>('[data-muted]');
    tl.to(mutedEls, { color: 'rgba(243,237,227,0.32)', duration: 0.7 }, 1.3);

    // Nav border and product strip border also soften
    const dividers = sticky.querySelectorAll<HTMLElement>('[data-divider]');
    tl.to(dividers, { borderColor: 'rgba(243,237,227,0.10)', duration: 0.7 }, 1.3);

    // CTA buttons invert for dark bg
    const ctaPrimary = sticky.querySelector<HTMLElement>('[data-cta-primary]');
    const ctaGhost   = sticky.querySelector<HTMLElement>('[data-cta-ghost]');
    if (ctaPrimary) tl.to(ctaPrimary, { backgroundColor: LIGHT, color: DARK, duration: 0.6 }, 1.3);
    if (ctaGhost)   tl.to(ctaGhost,   { color: 'rgba(243,237,227,0.45)', borderColor: 'rgba(243,237,227,0.15)', duration: 0.6 }, 1.3);

    // Frame 2 → 3
    tl.to(frames[2], { opacity: 0, duration: 0.5 }, 2.1)
      .to(frames[3], { opacity: 1, duration: 0.5 }, 2.1);

    // Frame 3 → 4 (puzzle-pb — assembled, dark bg, normal blend)
    tl.to(frames[3], { opacity: 0, duration: 0.5 }, 2.9)
      .to(frames[4], { opacity: 1, duration: 0.5 }, 2.9);

    // Progress bar fills as you scroll
    if (progressRef.current) {
      tl.fromTo(
        progressRef.current,
        { scaleY: 0, transformOrigin: 'top center' },
        { scaleY: 1, duration: 3.4 },
        0
      );
    }

    return () => { ScrollTrigger.getAll().forEach(t => t.kill()); };
  }, []);

  return (
    <section
      ref={sectionRef}
      style={{ height: '500vh', position: 'relative' }}
    >
      <div
        ref={stickyRef}
        style={{
          position: 'sticky',
          top: 0,
          height: '100dvh',
          backgroundColor: PAPER,
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
        }}
      >

        {/* ── Hero body — 2 column grid ──────────────────────────────── */}
        <div
          className="aurora-hero-grid"
          style={{
            flex: 1,
            display: 'grid',
            gridTemplateColumns: '55% 45%',
            minHeight: 0,
            paddingTop: '64px',
          }}
        >

          {/* ── Left: Text content ───────────────────────────────────── */}
          <div style={{
            padding: 'clamp(2.5rem, 4.5vw, 5.5rem) var(--px) clamp(2rem, 3vw, 3.5rem)',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'space-between',
            overflow: 'hidden',
          }}>

            {/* Top group: eyebrow + headline */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'clamp(1.5rem, 2.5vw, 2.5rem)' }}>

              {/* Eyebrow */}
              <div
                data-hero-reveal
                data-muted
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.75rem',
                }}
              >
                <span style={{
                  width: 5, height: 5,
                  background: RED,
                  display: 'inline-block',
                  flexShrink: 0,
                }} />
                <span style={{
                  fontFamily: 'var(--font-mono)',
                  fontSize: '0.6rem',
                  letterSpacing: '0.28em',
                  color: INK50,
                  textTransform: 'uppercase',
                }}>
                  Aurora · Ecossistema de IA Governada
                </span>
