/** Render a `MixedText` into HTML (sans/em/dot segments). */
function mixed(text: MixedText): string {
  return text
    .map((seg) => {
      if (seg.dot) return `<span class='dot'>${seg.text}</span>`;
      if (seg.em) return `<em>${seg.text}</em>`;
      return seg.text;
    })
    .join('');
}

